package org.apache.commons.lang3;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_31_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // A string containing a supplementary character (U+1F600, GRINNING FACE)
        String str = "Hello \uD83D\uDE00 World";
        // Search array containing only part of the surrogate pair
        char[] searchChars = {'\uD83D'};

        // The method should return false because the searchChars does not contain the complete supplementary character
        assertFalse(StringUtils.containsAny(str, searchChars));
    }
}

